const raw = $input.first().json || {};
const text = raw.output || raw.response || raw.text || raw.message || '';

const sectionRe = (tag) => new RegExp('\\[' + tag + '\\]([\\s\\S]*?)\\[\\/' + tag + '\\]', 'i');
const extract = (tag) => {
  const m = text.match(sectionRe(tag));
  return m ? m[1].trim() : '';
};

const resumen    = extract('RESUMEN_EJECUTIVO');
const comoVamos  = extract('COMO_VAMOS');
const proyectado = extract('PROYECTADO');
const detalles   = extract('DETALLES');
const metricasStr = extract('METRICAS_JSON');

let metricas = null;
let otSnapshot = null;
if (metricasStr) {
  try {
    const clean = metricasStr.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
    const parsed = JSON.parse(clean);
    metricas = parsed;
    otSnapshot = parsed.ot_futuras || [];
  } catch (e) {
    metricas = { parse_error: String(e), raw: metricasStr.substring(0, 500) };
    otSnapshot = [];
  }
}

const fallback = !resumen && !comoVamos && !proyectado;
const esc = (s) => String(s || '').replace(/'/g, "''");

return [{ json: {
  resumen:     resumen    || (fallback ? text : 'Sin resumen ejecutivo.'),
  como_vamos:  comoVamos  || '',
  proyectado:  proyectado || '',
  detalles:    detalles   || '',
  metricas:    metricas,
  ot_snapshot: otSnapshot || [],
  fecha_hoy:   new Date().toISOString().slice(0, 10),
  fallback,
  _sql_resumen:     esc(resumen || (fallback ? text : 'Sin resumen ejecutivo.')),
  _sql_como_vamos:  esc(comoVamos),
  _sql_proyectado:  esc(proyectado),
  _sql_detalles:    esc(detalles),
  _sql_metricas:    esc(JSON.stringify(metricas || {})),
  _sql_ot_snapshot: esc(JSON.stringify(otSnapshot || []))
} }];
